(ns episodes.layout-spec
  (:require [speclj.core :refer :all]
            [gherclj.core :as g]
            [gherclj.lifecycle :as lifecycle]
            [isaac.config.config-steps :as config-steps]
            [isaac.episodes.episode-steps :as episode-steps]
            [isaac.foundation.cli-steps :as cli-steps]
            [isaac.foundation.fs-steps :as fs-steps]
            [isaac.session.session-steps :as session-steps]
            [isaac.tool.tools-steps :as tools-steps]))

(describe "Episodes storage layout — one directory per session under sessions/<crew>/, episodes nested inside (isaac-b6w0)"

  (around [it]
    (binding [g/*state* (atom {})]
      (lifecycle/run-before-feature-hooks!)
      (try
        (it)
        (finally
          (lifecycle/run-after-feature-hooks!)))))

  (around [it]
    (binding [g/*state* (atom @g/*state*)]
      (lifecycle/run-before-scenario-hooks!)
      (try
        (it)
        (finally
          (lifecycle/run-after-scenario-hooks!)))))

  (it "a cold open on an episodes crew creates the session directory once and the first episode beneath it"
    ;; Given default Grover setup  (episodes/layout.feature:18)
    (g/with-step* "Given default Grover setup" "episodes/layout.feature" 18 (fn [] (isaac.session.session-steps/default-grover-setup)))
    ;; Given the isaac EDN file "config/crew/cordelia.edn" exists with:  (episodes/layout.feature:21)
    ;;   | path | value |  (episodes/layout.feature:22)
    ;;   | model | echo |  (episodes/layout.feature:23)
    ;;   | soul | You are Cordelia |  (episodes/layout.feature:24)
    ;;   | session-policy | :episodes |  (episodes/layout.feature:25)
    (g/with-step* "Given the isaac EDN file \"config/crew/cordelia.edn\" exists with:" "episodes/layout.feature" 21 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/crew/cordelia.edn" {:headers ["path" "value"], :rows [["model" "echo"] ["soul" "You are Cordelia"] ["session-policy" ":episodes"]], :header-line 22, :row-lines [23 24 25]})))
    ;; And the following model responses are queued:  (episodes/layout.feature:26)
    ;;   | type | content | model |  (episodes/layout.feature:27)
    ;;   | text | Charted, keep west | echo |  (episodes/layout.feature:28)
    (g/with-step* "And the following model responses are queued:" "episodes/layout.feature" 26 (fn [] (isaac.session.session-steps/responses-queued {:headers ["type" "content" "model"], :rows [["text" "Charted, keep west" "echo"]], :header-line 27, :row-lines [28]})))
    ;; When a charge is dispatched with:  (episodes/layout.feature:29)
    ;;   | key | value |  (episodes/layout.feature:30)
    ;;   | session-key | lantern-room |  (episodes/layout.feature:31)
    ;;   | crew | cordelia |  (episodes/layout.feature:32)
    ;;   | input | Light the lamp |  (episodes/layout.feature:33)
    (g/with-step* "When a charge is dispatched with:" "episodes/layout.feature" 29 (fn [] (isaac.session.session-steps/charge-dispatched-with {:headers ["key" "value"], :rows [["session-key" "lantern-room"] ["crew" "cordelia"] ["input" "Light the lamp"]], :header-line 30, :row-lines [31 32 33]})))
    ;; Then the isaac file "sessions/cordelia/lantern-room/session.edn" EDN contains:  (episodes/layout.feature:34)
    ;;   | path | value |  (episodes/layout.feature:35)
    ;;   | id | lantern-room |  (episodes/layout.feature:36)
    ;;   | crew | cordelia |  (episodes/layout.feature:37)
    ;;   | session-policy | :episodes |  (episodes/layout.feature:38)
    (g/with-step* "Then the isaac file \"sessions/cordelia/lantern-room/session.edn\" EDN contains:" "episodes/layout.feature" 34 (fn [] (isaac.foundation.fs-steps/isaac-file-edn-contains "sessions/cordelia/lantern-room/session.edn" {:headers ["path" "value"], :rows [["id" "lantern-room"] ["crew" "cordelia"] ["session-policy" ":episodes"]], :header-line 35, :row-lines [36 37 38]})))
    ;; And the directory "sessions/cordelia/lantern-room/episodes" has exactly 1 file  (episodes/layout.feature:39)
    (g/with-step* "And the directory \"sessions/cordelia/lantern-room/episodes\" has exactly 1 file" "episodes/layout.feature" 39 (fn [] (isaac.foundation.fs-steps/directory-has-exactly-n-files "sessions/cordelia/lantern-room/episodes" "1")))
    ;; And an episode exists for crew "cordelia" matching:  (episodes/layout.feature:40)
    ;;   | key | value |  (episodes/layout.feature:41)
    ;;   | id | #"\d{17}" |  (episodes/layout.feature:42)
    ;;   | status | open |  (episodes/layout.feature:43)
    ;;   | session-id | lantern-room |  (episodes/layout.feature:44)
    (g/with-step* "And an episode exists for crew \"cordelia\" matching:" "episodes/layout.feature" 40 (fn [] (isaac.episodes.episode-steps/episode-exists-for-crew-matching "cordelia" {:headers ["key" "value"], :rows [["id" "#\"\\d{17}\""] ["status" "open"] ["session-id" "lantern-room"]], :header-line 41, :row-lines [42 43 44]})))
    ;; And the isaac file "sessions/index.edn" EDN contains:  (episodes/layout.feature:45)
    ;;   | path | value |  (episodes/layout.feature:46)
    ;;   | lantern-room.crew | cordelia |  (episodes/layout.feature:47)
    ;;   | lantern-room.session-policy | :episodes |  (episodes/layout.feature:48)
    (g/with-step* "And the isaac file \"sessions/index.edn\" EDN contains:" "episodes/layout.feature" 45 (fn [] (isaac.foundation.fs-steps/isaac-file-edn-contains "sessions/index.edn" {:headers ["path" "value"], :rows [["lantern-room.crew" "cordelia"] ["lantern-room.session-policy" ":episodes"]], :header-line 46, :row-lines [47 48]})))
    ;; And session "lantern-room" has transcript matching:  (episodes/layout.feature:49)
    ;;   | type | message.role | message.content |  (episodes/layout.feature:50)
    ;;   | message | user | Light the lamp |  (episodes/layout.feature:51)
    ;;   | message | assistant | Charted, keep west |  (episodes/layout.feature:52)
    (g/with-step* "And session \"lantern-room\" has transcript matching:" "episodes/layout.feature" 49 (fn [] (isaac.session.session-steps/session-transcript-matching "lantern-room" {:headers ["type" "message.role" "message.content"], :rows [["message" "user" "Light the lamp"] ["message" "assistant" "Charted, keep west"]], :header-line 50, :row-lines [51 52]}))))

  (it "a successor episode after compaction is a sibling under the same session; the closed episode keeps its final counters"
    ;; Given default Grover setup  (episodes/layout.feature:18)
    (g/with-step* "Given default Grover setup" "episodes/layout.feature" 18 (fn [] (isaac.session.session-steps/default-grover-setup)))
    ;; Given the isaac EDN file "config/models/local.edn" exists with:  (episodes/layout.feature:55)
    ;;   | path | value |  (episodes/layout.feature:56)
    ;;   | model | test-model |  (episodes/layout.feature:57)
    ;;   | provider | grover |  (episodes/layout.feature:58)
    ;;   | context-window | 100 |  (episodes/layout.feature:59)
    (g/with-step* "Given the isaac EDN file \"config/models/local.edn\" exists with:" "episodes/layout.feature" 55 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/models/local.edn" {:headers ["path" "value"], :rows [["model" "test-model"] ["provider" "grover"] ["context-window" "100"]], :header-line 56, :row-lines [57 58 59]})))
    ;; And the isaac EDN file "config/crew/cordelia.edn" exists with:  (episodes/layout.feature:60)
    ;;   | path | value |  (episodes/layout.feature:61)
    ;;   | model | local |  (episodes/layout.feature:62)
    ;;   | soul | You are Cordelia |  (episodes/layout.feature:63)
    ;;   | session-policy | :episodes |  (episodes/layout.feature:64)
    (g/with-step* "And the isaac EDN file \"config/crew/cordelia.edn\" exists with:" "episodes/layout.feature" 60 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/crew/cordelia.edn" {:headers ["path" "value"], :rows [["model" "local"] ["soul" "You are Cordelia"] ["session-policy" ":episodes"]], :header-line 61, :row-lines [62 63 64]})))
    ;; And the isaac EDN file "config/models/gist.edn" exists with:  (episodes/layout.feature:65)
    ;;   | path | value |  (episodes/layout.feature:66)
    ;;   | model | gist |  (episodes/layout.feature:67)
    ;;   | provider | grover |  (episodes/layout.feature:68)
    (g/with-step* "And the isaac EDN file \"config/models/gist.edn\" exists with:" "episodes/layout.feature" 65 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/models/gist.edn" {:headers ["path" "value"], :rows [["model" "gist"] ["provider" "grover"]], :header-line 66, :row-lines [67 68]})))
    ;; And config file "isaac.edn" containing:  (episodes/layout.feature:69)
    (g/with-step* "And config file \"isaac.edn\" containing:" "episodes/layout.feature" 69 (fn [] (isaac.config.config-steps/config-file-containing "isaac.edn" "{:episodes {:gist-model :gist}}")))
    ;; And the following sessions exist:  (episodes/layout.feature:73)
    ;;   | name | crew | last-input-tokens |  (episodes/layout.feature:74)
    ;;   | lantern-room | cordelia | 85 |  (episodes/layout.feature:75)
    (g/with-step* "And the following sessions exist:" "episodes/layout.feature" 73 (fn [] (isaac.session.session-steps/sessions-exist {:headers ["name" "crew" "last-input-tokens"], :rows [["lantern-room" "cordelia" "85"]], :header-line 74, :row-lines [75]})))
    ;; And session "lantern-room" has transcript:  (episodes/layout.feature:76)
    ;;   | type | message.role | message.content |  (episodes/layout.feature:77)
    ;;   | message | user | old message one |  (episodes/layout.feature:78)
    ;;   | message | assistant | old response one |  (episodes/layout.feature:79)
    ;;   | message | user | old message two |  (episodes/layout.feature:80)
    ;;   | message | assistant | old response two |  (episodes/layout.feature:81)
    (g/with-step* "And session \"lantern-room\" has transcript:" "episodes/layout.feature" 76 (fn [] (isaac.session.session-steps/session-has-transcript "lantern-room" {:headers ["type" "message.role" "message.content"], :rows [["message" "user" "old message one"] ["message" "assistant" "old response one"] ["message" "user" "old message two"] ["message" "assistant" "old response two"]], :header-line 77, :row-lines [78 79 80 81]})))
    ;; And the following model responses are queued:  (episodes/layout.feature:82)
    ;;   | type | content | model |  (episodes/layout.feature:83)
    ;;   | text | Full summary of prior | test-model |  (episodes/layout.feature:84)
    ;;   | text | 1-4: Prior voyage | gist |  (episodes/layout.feature:85)
    ;;   | text | New response | test-model |  (episodes/layout.feature:86)
    (g/with-step* "And the following model responses are queued:" "episodes/layout.feature" 82 (fn [] (isaac.session.session-steps/responses-queued {:headers ["type" "content" "model"], :rows [["text" "Full summary of prior" "test-model"] ["text" "1-4: Prior voyage" "gist"] ["text" "New response" "test-model"]], :header-line 83, :row-lines [84 85 86]})))
    ;; When the user sends "new input" on session "lantern-room"  (episodes/layout.feature:87)
    (g/with-step* "When the user sends \"new input\" on session \"lantern-room\"" "episodes/layout.feature" 87 (fn [] (isaac.session.session-steps/user-sends-on-session "new input" "lantern-room")))
    ;; Then the directory "sessions/cordelia/lantern-room/episodes" has exactly 2 files  (episodes/layout.feature:88)
    (g/with-step* "Then the directory \"sessions/cordelia/lantern-room/episodes\" has exactly 2 files" "episodes/layout.feature" 88 (fn [] (isaac.foundation.fs-steps/directory-has-exactly-n-files "sessions/cordelia/lantern-room/episodes" "2")))
    ;; And crew "cordelia" has 2 episodes  (episodes/layout.feature:89)
    (g/with-step* "And crew \"cordelia\" has 2 episodes" "episodes/layout.feature" 89 (fn [] (isaac.episodes.episode-steps/crew-has-n-episodes "cordelia" "2")))
    ;; And an episode exists for crew "cordelia" matching:  (episodes/layout.feature:90)
    ;;   | key | value |  (episodes/layout.feature:91)
    ;;   | status | closed |  (episodes/layout.feature:92)
    ;;   | session-id | lantern-room |  (episodes/layout.feature:93)
    ;;   | last-input-tokens | 85 |  (episodes/layout.feature:94)
    (g/with-step* "And an episode exists for crew \"cordelia\" matching:" "episodes/layout.feature" 90 (fn [] (isaac.episodes.episode-steps/episode-exists-for-crew-matching "cordelia" {:headers ["key" "value"], :rows [["status" "closed"] ["session-id" "lantern-room"] ["last-input-tokens" "85"]], :header-line 91, :row-lines [92 93 94]})))
    ;; And an episode exists for crew "cordelia" matching:  (episodes/layout.feature:95)
    ;;   | key | value |  (episodes/layout.feature:96)
    ;;   | status | open |  (episodes/layout.feature:97)
    ;;   | session-id | lantern-room |  (episodes/layout.feature:98)
    ;;   | parent-episode | #"\d{17}" |  (episodes/layout.feature:99)
    (g/with-step* "And an episode exists for crew \"cordelia\" matching:" "episodes/layout.feature" 95 (fn [] (isaac.episodes.episode-steps/episode-exists-for-crew-matching "cordelia" {:headers ["key" "value"], :rows [["status" "open"] ["session-id" "lantern-room"] ["parent-episode" "#\"\\d{17}\""]], :header-line 96, :row-lines [97 98 99]})))
    ;; And the isaac file "sessions/cordelia/lantern-room/session.edn" EDN contains:  (episodes/layout.feature:100)
    ;;   | path | value |  (episodes/layout.feature:101)
    ;;   | id | lantern-room |  (episodes/layout.feature:102)
    ;;   | crew | cordelia |  (episodes/layout.feature:103)
    ;;   | session-policy | :episodes |  (episodes/layout.feature:104)
    (g/with-step* "And the isaac file \"sessions/cordelia/lantern-room/session.edn\" EDN contains:" "episodes/layout.feature" 100 (fn [] (isaac.foundation.fs-steps/isaac-file-edn-contains "sessions/cordelia/lantern-room/session.edn" {:headers ["path" "value"], :rows [["id" "lantern-room"] ["crew" "cordelia"] ["session-policy" ":episodes"]], :header-line 101, :row-lines [102 103 104]})))
    ;; And session "lantern-room" has transcript matching:  (episodes/layout.feature:105)
    ;;   | type | message.role | message.content |  (episodes/layout.feature:106)
    ;;   | message | user | new input |  (episodes/layout.feature:107)
    ;;   | message | assistant | New response |  (episodes/layout.feature:108)
    (g/with-step* "And session \"lantern-room\" has transcript matching:" "episodes/layout.feature" 105 (fn [] (isaac.session.session-steps/session-transcript-matching "lantern-room" {:headers ["type" "message.role" "message.content"], :rows [["message" "user" "new input"] ["message" "assistant" "New response"]], :header-line 106, :row-lines [107 108]}))))

  (it "a session-level pin set once applies to every episode of that session"
    ;; Given default Grover setup  (episodes/layout.feature:18)
    (g/with-step* "Given default Grover setup" "episodes/layout.feature" 18 (fn [] (isaac.session.session-steps/default-grover-setup)))
