  (it "a chronicle session carries the policy stamp and the listing shows the policy column for both kinds"
    ;; Given default Grover setup  (episodes/layout.feature:18)
    (g/with-step* "Given default Grover setup" "episodes/layout.feature" 18 (fn [] (isaac.session.session-steps/default-grover-setup)))
    ;; Given the isaac EDN file "config/crew/cordelia.edn" exists with:  (episodes/layout.feature:146)
    ;;   | path | value |  (episodes/layout.feature:147)
