    (g/with-step* "Given the isaac EDN file \"config/crew/cordelia.edn\" exists with:" "episodes/layout.feature" 146 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/crew/cordelia.edn" {:headers ["path" "value"], :rows [["model" "echo"] ["soul" "You are Cordelia"] ["session-policy" ":episodes"]], :header-line 147, :row-lines [148 149 150]})))
    ;; And the following model responses are queued:  (episodes/layout.feature:151)
    ;;   | type | content | model |  (episodes/layout.feature:152)
    ;;   | text | Aye | echo |  (episodes/layout.feature:153)
    ;;   | text | Lit | echo |  (episodes/layout.feature:154)
    (g/with-step* "And the following model responses are queued:" "episodes/layout.feature" 151 (fn [] (isaac.session.session-steps/responses-queued {:headers ["type" "content" "model"], :rows [["text" "Aye" "echo"] ["text" "Lit" "echo"]], :header-line 152, :row-lines [153 154]})))
